/**
 * Data Studio's sample data, generated by fixed rules so it never changes:
 * a messy bookings export to clean, sales tables to query, and training
 * results to analyse.
 */
import type { Dataset, DataStudioState, Value } from './schema'

export const CLIENT_NAMES = [
  'Harbour Foods',
  'Northgate Motors',
  'Brightpath Clinics',
  'Lind Studio',
  'Meadow Care Homes',
  'Okafor Build',
  'Begum Textiles',
  'Martin Bakery',
  'Riverside Dental',
  'Gonzalez Design',
  'Haddad Trading',
  'Steelway Engineering',
]
const REGIONS = ['North', 'South', 'West']
const SOURCES = ['Website', 'Referral', 'Event']

/** A messy export of 36 review bookings: spacing, capitals, formats, duplicates and a test row. */
export function bookingsRaw(): Dataset {
  const rows: Value[][] = []
  for (let i = 0; i < 36; i++) {
    const name = CLIENT_NAMES[(i * 5) % CLIENT_NAMES.length]
    const client =
      i % 4 === 0
        ? name.toLowerCase()
        : i % 5 === 1
          ? `  ${name} `
          : i % 7 === 3
            ? name.toUpperCase()
            : name
    const regionName = REGIONS[(i * 2) % 3]
    const region =
      i % 3 === 0
        ? regionName.toLowerCase()
        : i % 4 === 1
          ? ` ${regionName} `
          : regionName
    const day = (i % 28) + 1
    const month = i < 18 ? 3 : 4
    const date =
      i % 3 === 0
        ? `${day}/${String(month).padStart(2, '0')}/2026`
        : `2026-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`
    const amount = 600 + ((i * 137) % 9) * 150
    const value =
      i % 2 === 0
        ? `£${amount.toLocaleString('en-GB')}`
        : i % 3 === 0
          ? `${amount}.00`
          : String(amount)
    const status =
      i % 6 === 5 ? 'Cancelled' : ['Confirmed', 'confirmed', 'CONFIRMED'][i % 3]
    rows.push([`B-${2001 + i}`, date, client, region, SOURCES[i % 3], value, status])
  }
  // The export repeated some bookings, and included a test booking.
  rows.splice(9, 0, [...rows[3]])
  rows.splice(20, 0, [...rows[16]])
  rows.splice(31, 0, [...rows[28]])
  rows.push(['TEST-001', '2026-03-31', '', '', 'Website', '0', 'confirmed'])
  return {
    name: 'bookings',
    description:
      'Free-review bookings exported from the website, March and April. Not cleaned.',
    columns: [
      { name: 'booking_id', type: 'text' },
      { name: 'booked_on', type: 'text' },
      { name: 'client', type: 'text' },
      { name: 'region', type: 'text' },
      { name: 'source', type: 'text' },
      { name: 'value', type: 'text' },
      { name: 'status', type: 'text' },
    ],
    rows,
    steps: [],
  }
}

export const SECTORS: Record<string, string> = {
  'Harbour Foods': 'Retail',
  'Northgate Motors': 'Manufacturing',
  'Brightpath Clinics': 'Healthcare',
  'Lind Studio': 'Retail',
  'Meadow Care Homes': 'Healthcare',
  'Okafor Build': 'Manufacturing',
  'Begum Textiles': 'Manufacturing',
  'Martin Bakery': 'Retail',
  'Riverside Dental': 'Healthcare',
  'Gonzalez Design': 'Retail',
  'Haddad Trading': 'Retail',
  'Steelway Engineering': 'Manufacturing',
}

export function clients(): Dataset {
  return {
    name: 'clients',
    description: 'Every client on our books.',
    columns: [
      { name: 'client_id', type: 'text' },
      { name: 'name', type: 'text' },
      { name: 'sector', type: 'text' },
      { name: 'region', type: 'text' },
    ],
    rows: CLIENT_NAMES.map((name, i) => [
      `C${101 + i}`,
      name,
      SECTORS[name],
      REGIONS[i % 3],
    ]),
    steps: [],
  }
}

const SERVICES = ['Advisory', 'Training', 'Audit support']

/** 60 orders in the first quarter. Two clients (Lind Studio, Martin Bakery) ordered nothing. */
export function orders(): Dataset {
  const active = CLIENT_NAMES.map((_, i) => `C${101 + i}`).filter(
    (id) => id !== 'C104' && id !== 'C108',
  )
  const rows: Value[][] = Array.from({ length: 60 }, (_, i) => {
    const month = i < 18 ? 1 : i < 38 ? 2 : 3
    const day = ((i * 7) % 27) + 1
    const service = SERVICES[(i * 2) % 3]
    const base = service === 'Advisory' ? 2400 : service === 'Training' ? 1200 : 1800
    const amount = base + ((i * 53) % 7) * 150 + (i % 4) * 25
    return [
      `O-${5001 + i}`,
      active[(i * 3) % active.length],
      `2026-0${month}-${String(day).padStart(2, '0')}`,
      service,
      amount,
    ]
  })
  return {
    name: 'orders',
    description: 'Orders placed in January to March 2026.',
    columns: [
      { name: 'order_id', type: 'text' },
      { name: 'client_id', type: 'text' },
      { name: 'order_date', type: 'date' },
      { name: 'service', type: 'text' },
      { name: 'amount', type: 'number' },
    ],
    rows,
    steps: [],
  }
}

/**
 * Skills test scores of 40 staff before and after a training programme.
 * Those who attended improve more on average, and more hours go with more
 * improvement, but attendance was voluntary.
 */
export function training(): Dataset {
  const teams = ['Advisory', 'Audit', 'Tax', 'Operations']
  const rows: Value[][] = Array.from({ length: 40 }, (_, i) => {
    const attended = i % 5 !== 0 && i % 7 !== 2
    const hours = attended ? 4 + ((i * 3) % 13) : (i * 2) % 3
    const before = 52 + ((i * 11) % 23)
    const noise = ((i * 17) % 9) - 4
    const after = Math.min(
      100,
      before + Math.round(hours * 0.9) + (attended ? 3 : 0) + noise,
    )
    return [`E${301 + i}`, teams[i % 4], attended ? 'yes' : 'no', hours, before, after]
  })
  return {
    name: 'training',
    description: 'Skills test scores before and after the spring training programme.',
    columns: [
      { name: 'employee', type: 'text' },
      { name: 'team', type: 'text' },
      { name: 'attended', type: 'text' },
      { name: 'hours', type: 'number' },
      { name: 'score_before', type: 'number' },
      { name: 'score_after', type: 'number' },
    ],
    rows,
    steps: [],
  }
}

export function sampleStudio(): DataStudioState {
  return {
    datasets: [bookingsRaw(), clients(), orders(), training()],
    queries: [],
    dashboard: { title: 'Dashboard', tiles: [] },
    questions: [],
  }
}
